/**
 * freq_div.v
 *
 * Frequency Divider Module - Modular Implementation
 *
 * Inputs:
 *   CLK_in - 100 MHz input clock
 *   RST    - Asynchronous active-high reset
 *
 * Outputs:
 *   CLK_50 - 50 MHz clock output (CLK_in / 2)
 *   CLK_10 - 10 MHz clock output (CLK_in / 10)
 *   CLK_1  -  1 MHz clock output (CLK_in / 100)
 *
 * Each output clock is generated by a dedicated always block with its own counter,
 * toggling output signals at half the desired output period count for accurate division.
 */

module freq_div (
    input  wire CLK_in,
    input  wire RST,
    output reg  CLK_50,
    output reg  CLK_10,
    output reg  CLK_1
);

    // Half-period counts for toggling outputs
    localparam CNT_50_HALF  = 1 - 1;  // 1 toggle every clock cycle (divide by 2)
    localparam CNT_10_HALF  = 5 - 1;  // Toggle every 5 CLK_in cycles (divide by 10)
    localparam CNT_100_HALF = 50 - 1; // Toggle every 50 CLK_in cycles (divide by 100)

    // Counter width calculations
    // 1 requires 1 bit, 5 requires 3 bits, 50 requires 6 bits
    reg       [0:0]  cnt_50;   // Actually not needed as toggled every clock, but kept for style
    reg [2:0] cnt_10;
    reg [5:0] cnt_100;

    // CLK_50 block: toggles every clock cycle (divide by 2)
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            CLK_50 <= 1'b0;
        end else begin
            CLK_50 <= ~CLK_50;
        end
    end

    // CLK_10 block: toggle every 5 CLK_in cycles
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            cnt_10 <= 3'd0;
            CLK_10 <= 1'b0;
        end else if (cnt_10 == CNT_10_HALF) begin
            cnt_10 <= 3'd0;
            CLK_10 <= ~CLK_10;
        end else begin
            cnt_10 <= cnt_10 + 1'b1;
        end
    end

    // CLK_1 block: toggle every 50 CLK_in cycles
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            cnt_100 <= 6'd0;
            CLK_1 <= 1'b0;
        end else if (cnt_100 == CNT_100_HALF) begin
            cnt_100 <= 6'd0;
            CLK_1 <= ~CLK_1;
        end else begin
            cnt_100 <= cnt_100 + 1'b1;
        end
    end

endmodule